// Specialized kernel for cols == 1024: 128 threads, each reads 8 floats via two float4 loads.
__global__ void row_logsumexp_1024_kernel(
    const float* __restrict__ x,
    float* __restrict__ out,
    int rows)
{
    int row = blockIdx.x;
    if (row >= rows) return;

    const float4* row_ptr4 = reinterpret_cast<const float4*>(x + row * 1024);
    int tid = threadIdx.x;  // 0..127
    int lane = tid & 31;
    int warp = tid >> 5;    // 0..3

    // Each thread loads 8 floats at two float4 positions: tid and tid+128
    float4 a0 = row_ptr4[tid];        // floats [tid*4 .. tid*4+3]
    float4 a1 = row_ptr4[tid + 128];  // floats [(tid+128)*4 .. (tid+128)*4+3]

    // Thread-local max over 8 values
    float tmax = fmaxf(fmaxf(fmaxf(a0.x, a0.y), fmaxf(a0.z, a0.w)),
                       fmaxf(fmaxf(a1.x, a1.y), fmaxf(a1.z, a1.w)));

    // Warp reduce max
    for (int offset = 16; offset > 0; offset >>= 1)
        tmax = fmaxf(tmax, __shfl_down_sync(0xffffffff, tmax, offset));

    __shared__ float smem[4];
    if (lane == 0) smem[warp] = tmax;
    __syncthreads();

    // 4-warp block reduce max (done by thread 0)
    if (tid == 0) {
        float bmax = fmaxf(fmaxf(smem[0], smem[1]), fmaxf(smem[2], smem[3]));
        smem[0] = bmax;
    }
    __syncthreads();
    float row_max = smem[0];

    // Thread-local sum of exp(v - row_max) over 8 values
    float tsum = __expf(a0.x - row_max) + __expf(a0.y - row_max)
               + __expf(a0.z - row_max) + __expf(a0.w - row_max)
               + __expf(a1.x - row_max) + __expf(a1.y - row_max)
               + __expf(a1.z - row_max) + __expf(a1.w - row_max);

    // Warp reduce sum
    for (int offset = 16; offset > 0; offset >>= 1)
        tsum += __shfl_down_sync(0xffffffff, tsum, offset);

    if (lane == 0) smem[warp] = tsum;
    __syncthreads();

    if (tid == 0) {
        float bsum = smem[0] + smem[1] + smem[2] + smem[3];
