    if (lane == 0) smem_g[warp] = tmax;
    __syncthreads();

    if (tid < nwarps) {
        tmax = smem_g[tid];
        for (int offset = nwarps >> 1; offset > 0; offset >>= 1)
            tmax = fmaxf(tmax, __shfl_down_sync(0xffffffff, tmax, offset));
