// In-place sigmoid kernel using float4 vectorized loads/stores.
// numel must be divisible by 4 for the fast path; scalar fallback handles remainder.
__global__ void sigmoid_inplace_kernel(
    float* __restrict__ x,
    long numel4)  // number of float4 elements
{
    long idx = (long)blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= numel4) return;

    float4* ptr = reinterpret_cast<float4*>(x);
    float4 v = ptr[idx];
    v.x = 1.0f / (1.0f + __expf(-v.x));
    v.y = 1.0f / (1.0f + __expf(-v.y));
    v.z = 1.0f / (1.0f + __expf(-v.z));
    v.w = 1.0f / (1.0f + __expf(-v.w));
    ptr[idx] = v;
}

